import { computed, getCurrentInstance, nextTick, onBeforeUnmount, onMounted, ref, watch, type Ref } from "vue";
import { layerManager, type Layer } from "./layers";

export function useControllable<T>(props: Record<string, any>, key: string, emit: (...args: any[]) => void, fallback: T) {
  const local = ref<T>(fallback) as Ref<T>;
  const read = () => props[key] as T | undefined;
  return computed<T>({
    get() { const supplied = read(); return supplied === undefined ? local.value : supplied; },
    set(value) { if (read() === undefined) local.value = value; emit(`update:${key}`, value); },
  });
}

export function useMediaQuery(query: string) {
  const matches = ref(false);
  let disconnect: (() => void) | undefined;
  onMounted(() => {
    if (typeof window.matchMedia !== "function") return;
    const media = window.matchMedia(query);
    const update = () => { matches.value = media.matches; };
    update();
    media.addEventListener?.("change", update);
    disconnect = () => media.removeEventListener?.("change", update);
  });
  onBeforeUnmount(() => disconnect?.());
  return matches;
}
export function useReducedMotion() { return useMediaQuery("(prefers-reduced-motion: reduce)"); }

const lockedProperties = ["overflow", "position", "top", "left", "right", "width"] as const;
let scrollOwners = 0;
let unlockPage: (() => void) | undefined;
function acquirePage() {
  if (scrollOwners++ === 0) {
    const body = document.body.style;
    const saved = lockedProperties.map(name => ({ name, value: body.getPropertyValue(name), priority: body.getPropertyPriority(name) }));
    const x = window.scrollX, y = window.scrollY;
    body.setProperty("overflow", "hidden");
    body.setProperty("position", "fixed");
    body.setProperty("left", `${-x}px`);
    body.setProperty("top", `${-y}px`);
    body.setProperty("right", "0px");
    body.setProperty("width", "100%");
    unlockPage = () => {
      for (const entry of saved) {
        if (entry.value) body.setProperty(entry.name, entry.value, entry.priority);
        else body.removeProperty(entry.name);
      }
      const root = document.documentElement.style;
      const behavior = root.getPropertyValue("scroll-behavior");
      const priority = root.getPropertyPriority("scroll-behavior");
      root.setProperty("scroll-behavior", "auto");
      window.scrollTo(x, y);
      if (behavior) root.setProperty("scroll-behavior", behavior, priority);
      else root.removeProperty("scroll-behavior");
    };
  }
  let released = false;
  return () => {
    if (released) return;
    released = true;
    if (--scrollOwners === 0) { unlockPage?.(); unlockPage = undefined; }
  };
}
export function useScrollLock(locked: Ref<boolean>) {
  let mounted = false;
  let release: (() => void) | undefined;
  const update = (value: boolean) => {
    if (!mounted) return;
    if (value && !release) release = acquirePage();
    if (!value && release) { release(); release = undefined; }
  };
  onMounted(() => { mounted = true; update(locked.value); });
  watch(locked, update);
  onBeforeUnmount(() => { release?.(); release = undefined; mounted = false; });
}

export function resolveElement<T extends Element = HTMLElement>(value: unknown): T | null {
  if (!value) return null;
  const unwrapped = (value as { $el?: unknown }).$el ?? value;
  return typeof (unwrapped as Element).nodeType === "number" && (unwrapped as Element).nodeType === 1 ? unwrapped as T : null;
}
const focusable = 'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])';
function createLayer(modal: boolean, panel?: { readonly value: unknown }): Layer {
  return { key: Symbol("orvui-layer"), modal, owner: getCurrentInstance(), surface: () => resolveElement(panel?.value), returnTo: null };
}
export function useOverlay(open: Ref<boolean>, panel: Ref<HTMLElement | null>, close: () => void, initialFocus?: () => HTMLElement | undefined) {
  const layer = createLayer(true, panel);
  let mounted = false;
  let revision = 0;
  const sync = async (value: boolean) => {
    const current = ++revision;
    if (!mounted) return;
    if (!value) { layerManager.detach(layer, true); return; }
    if (!layerManager.attach(layer)) return;
    await nextTick();
    if (!mounted || current !== revision || !open.value || !layerManager.top(layer)) return;
    (initialFocus?.() ?? layer.surface()?.querySelector<HTMLElement>(focusable) ?? layer.surface())?.focus({ preventScroll: true });
  };
  const onKey = (event: KeyboardEvent) => {
    if (event.defaultPrevented || !open.value) return;
    if (event.key === "Escape" && layerManager.top(layer)) {
      event.preventDefault(); event.stopPropagation(); close(); return;
    }
    if (event.key !== "Tab" || !layerManager.modal(layer)) return;
    const candidates = new Set<HTMLElement>();
    for (const surface of layerManager.scopes(layer)) {
      for (const node of surface.querySelectorAll<HTMLElement>(focusable)) {
        if (node.getClientRects().length > 0 && !node.closest("[inert]")) candidates.add(node);
      }
    }
    event.preventDefault();
    const nodes = [...candidates];
    if (!nodes.length) { layer.surface()?.focus(); return; }
    const position = nodes.indexOf(document.activeElement as HTMLElement);
    const next = position < 0 ? (event.shiftKey ? nodes.length - 1 : 0) : (position + (event.shiftKey ? -1 : 1) + nodes.length) % nodes.length;
    nodes[next].focus();
  };
  useScrollLock(open);
  onMounted(() => { mounted = true; document.addEventListener("keydown", onKey); void sync(open.value); });
  watch(open, value => void sync(value));
  onBeforeUnmount(() => { mounted = false; revision++; document.removeEventListener("keydown", onKey); layerManager.detach(layer, true); });
  return {
    isTop: () => open.value && layerManager.top(layer),
    containsHigher: (target: EventTarget | null) => layerManager.higher(layer, target),
    containsOwnedPortal: (target: HTMLElement) => layerManager.containsPortal(layer.owner, target),
  };
}
export function useFloatingLayer(open: Ref<boolean>, panel?: { readonly value: unknown }) {
  const layer = createLayer(false, panel);
  let mounted = false;
  let unregister: (() => void) | undefined;
  const sync = (value: boolean) => {
    if (!mounted) return;
    if (value) layerManager.attach(layer); else layerManager.detach(layer, false);
  };
  onMounted(() => { mounted = true; unregister = layerManager.portal(layer.owner, layer.surface); sync(open.value); });
  watch(open, sync, { flush: "sync" });
  onBeforeUnmount(() => { mounted = false; unregister?.(); layerManager.detach(layer, false); });
  const isTop = () => open.value && layerManager.top(layer);
  return {
    isTop,
    claimEscape(event: KeyboardEvent) {
      if (event.key !== "Escape" || event.defaultPrevented || !isTop()) return false;
      event.preventDefault(); event.stopImmediatePropagation(); return true;
    },
    containsHigher: (target: EventTarget | null) => layerManager.higher(layer, target),
  };
}
export function useEventListener(target: () => EventTarget | null | undefined, event: string, handler: EventListener, options?: AddEventListenerOptions) {
  let remove: (() => void) | undefined;
  onMounted(() => { const element = target(); element?.addEventListener(event, handler, options); remove = () => element?.removeEventListener(event, handler, options); });
  onBeforeUnmount(() => remove?.());
}

export const EASE_OUT = [0.16, 1, 0.3, 1] as const;
export const EASE_IN_OUT = [0.77, 0, 0.175, 1] as const;
export const EASE_DRAWER = [0.32, 0.72, 0, 1] as const;
export const EASE_OUT_CSS = "cubic-bezier(0.16,1,0.3,1)";
export const SPRING_PRESS = {
  type: "spring",
  stiffness: 500,
  damping: 30,
  mass: 0.6,
} as const;
export const SPRING_SWAP = {
  type: "spring",
  stiffness: 460,
  damping: 30,
  mass: 0.55,
} as const;
export const SPRING_PANEL = {
  type: "spring",
  stiffness: 420,
  damping: 40,
  mass: 0.5,
} as const;
export const SPRING_LAYOUT = {
  type: "spring",
  stiffness: 360,
  damping: 32,
  mass: 0.6,
} as const;
export const SPRING_MOUSE = { stiffness: 200, damping: 15, mass: 0.3 } as const;
export const SPRING_GLIDE = { stiffness: 700, damping: 50, mass: 0.5 } as const;
export const SPRING_TIMELINE = {
  type: "spring",
  stiffness: 120,
  damping: 24,
  mass: 1,
} as const;

import type { ComponentInternalInstance } from "vue";

type Surface = () => HTMLElement | null;
export interface Layer {
  key: symbol;
  modal: boolean;
  owner: ComponentInternalInstance | null;
  surface: Surface;
  returnTo: HTMLElement | null;
}
const active: Layer[] = [];
const portals = new Set<{ owner: ComponentInternalInstance | null; surface: Surface }>();

function belongsTo(child: ComponentInternalInstance | null, parent: ComponentInternalInstance | null) {
  if (!parent) return false;
  for (let node = child; node; node = node.parent) if (node === parent) return true;
  return false;
}
function later(layer: Layer) {
  const index = active.indexOf(layer);
  return index < 0 ? [] : active.slice(index + 1);
}
export const layerManager = {
  attach(layer: Layer) {
    if (active.includes(layer)) return false;
    layer.returnTo = document.activeElement as HTMLElement | null;
    const before = active.findIndex(entry => entry.owner !== layer.owner && belongsTo(entry.owner, layer.owner));
    active.splice(before < 0 ? active.length : before, 0, layer);
    return true;
  },
  detach(layer: Layer, restore: boolean) {
    const index = active.indexOf(layer);
    if (index < 0) return;
    const wasLast = index === active.length - 1;
    const surface = layer.surface();
    for (const successor of later(layer)) {
      if (successor.returnTo && surface?.contains(successor.returnTo)) successor.returnTo = layer.returnTo;
    }
    active.splice(index, 1);
    if (restore && wasLast && layer.returnTo?.isConnected) layer.returnTo.focus({ preventScroll: true });
  },
  top(layer: Layer) { return active.at(-1) === layer; },
  modal(layer: Layer) { return active.slice().reverse().find(entry => entry.modal) === layer; },
  higher(layer: Layer, target: EventTarget | null) {
    return !!target && typeof (target as Node).nodeType === "number" && later(layer).some(entry => entry.surface()?.contains(target as Node));
  },
  scopes(layer: Layer) {
    const result = [layer.surface()];
    for (const entry of later(layer)) if (!entry.modal && belongsTo(entry.owner, layer.owner)) result.push(entry.surface());
    return result.filter((surface): surface is HTMLElement => surface !== null);
  },
  portal(owner: ComponentInternalInstance | null, surface: Surface) {
    const portal = { owner, surface };
    portals.add(portal);
    return () => portals.delete(portal);
  },
  containsPortal(owner: ComponentInternalInstance | null, target: HTMLElement) {
    for (const portal of portals) {
      const node = portal.surface();
      if (node && belongsTo(portal.owner, owner) && target.contains(node)) return true;
    }
    return false;
  },
};

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: unknown[]) {
  const combined = clsx(...inputs as ClassValue[]);
  return twMerge(combined);
}
export function clamp(value: number, min: number, max: number) {
  const aboveFloor = Math.max(min, value);
  return Math.min(aboveFloor, max);
}

import {
  computed, inject, nextTick, onBeforeUnmount, onMounted, ref, shallowRef,
  useId, watch, type InjectionKey, type Ref,
} from "vue";
import { useMotionState } from "../state";
import { useFloatingLayer, useReducedMotion } from "../../lib/composables";

export interface SearchItem {
  value: string;
  label: string;
  keywords: string[];
  disabled: boolean;
  groupId?: string;
  id: string;
  element: HTMLElement | null;
}
export type SearchController = ReturnType<typeof createSearchController>;
export const ComboboxContext: InjectionKey<SearchController> = Symbol("orvui-combobox");
export const MultiSelectContext: InjectionKey<SearchController> = Symbol("orvui-multi-select");
export const ComboboxGroupContext: InjectionKey<string> = Symbol("orvui-combobox-group");
export const MultiSelectGroupContext: InjectionKey<string> = Symbol("orvui-multi-select-group");

export function useSearchContext(multiple = false, name = "Component") {
  const controller = inject(multiple ? MultiSelectContext : ComboboxContext);
  if (!controller) throw new Error(`${name} must be used inside ${multiple ? "MultiSelect" : "Combobox"}`);
  return controller;
}
export function useMultiSelectContext(name = "Component") {
  return useSearchContext(true, name);
}
export function mergeRefs<T>(...destinations: (Ref<T | null> | ((value: T | null) => void) | undefined)[]) {
  return (element: T | null) => {
    destinations.forEach(destination => {
      if (typeof destination === "function") destination(element);
      else if (destination) destination.value = element;
    });
  };
}

function folded(text: string) { return text.toLocaleLowerCase().trim(); }
function subsequence(text: string, query: string) {
  let cursor = 0;
  for (const letter of query) {
    const index = text.indexOf(letter, cursor);
    if (index < 0) return false;
    cursor = index + 1;
  }
  return true;
}
function sameItem(first: SearchItem | undefined, second: SearchItem) {
  if (!first) return false;
  return first.value === second.value && first.label === second.label
    && first.id === second.id && first.element === second.element
    && first.disabled === second.disabled && first.groupId === second.groupId
    && first.keywords.length === second.keywords.length
    && first.keywords.every((word, index) => word === second.keywords[index]);
}

export function createSearchController(props: Record<string, any>, emit: (...args: any[]) => void, multiple = false) {
  const value = useMotionState<string | string[] | undefined>(props, emit, "modelValue", props.defaultValue ?? (multiple ? [] : undefined));
  const open = useMotionState<boolean>(props, emit, "open", props.defaultOpen ?? false);
  const query = useMotionState<string>(props, emit, "query", props.defaultQuery ?? "");
  const id = useId();
  const triggerId = `${id}-trigger`, inputId = `${id}-input`, listId = `${id}-list`, activeLayoutId = `${id}-active`;
  const inputRef = ref<HTMLInputElement | null>(null);
  const triggerRef = ref<HTMLElement | null>(null);
  const contentRef = ref<HTMLElement | null>(null);
  const items = shallowRef(new Map<string, SearchItem>());
  const layer = useFloatingLayer(open, contentRef);
  const reduce = useReducedMotion();
  const disabled = computed(() => !!props.disabled);
  const visited = ref(open.value);
  const exitQuery = ref(query.value);
  const cursor = ref<{ key: string; query: string } | null>(null);
  const visibleQuery = computed(() => open.value ? query.value : exitQuery.value);
  let disposed = false;

  function isVisible(key: string): boolean {
    const option = items.value.get(key);
    if (!option) return true;
    const search = folded(visibleQuery.value);
    if (props.filter) return props.filter(key, search, [option.label, ...option.keywords]);
    return subsequence(folded([key, option.label, ...option.keywords].join(" ")), search);
  }
  const visible = computed(() => [...items.value.values()].filter(option => isVisible(option.value)));
  const available = computed(() => visible.value.filter(option => !option.disabled));
  const activeValue = computed(() => {
    if (!visited.value) return null;
    const choice = cursor.value;
    if (choice?.query === visibleQuery.value && available.value.some(option => option.value === choice.key)) return choice.key;
    const selected = multiple ? (value.value as string[] | undefined)?.[0] : value.value;
    return available.value.find(option => option.value === selected)?.value ?? available.value[0]?.value ?? null;
  });
  const activeItemId = computed(() => activeValue.value === null ? undefined : items.value.get(activeValue.value)?.id);
  function registerItem(option: SearchItem) {
    if (sameItem(items.value.get(option.value), option)) return;
    items.value = new Map([...items.value, [option.value, option]]);
  }
  function unregisterItem(key: string) {
    if (!items.value.has(key)) return;
    const remaining = new Map(items.value);
    remaining.delete(key);
    items.value = remaining;
  }
  function focusInput() {
    void nextTick(() => { if (!disposed) inputRef.value?.focus({ preventScroll: true }); });
  }
  function setOpen(requested: boolean, restoreFocus = false) {
    if (requested && disabled.value) return;
    if (requested) {
      visited.value = true;
      open.value = true;
      focusInput();
      return;
    }
    exitQuery.value = query.value;
    open.value = false;
    query.value = "";
    if (restoreFocus) focusInput();
  }
  function setActiveValue(key: string | null) {
    cursor.value = key === null ? null : { key, query: visibleQuery.value };
  }
  function moveActive(direction: 1 | -1 | "first" | "last") {
    if (!open.value) return;
    const choices = available.value;
    if (!choices.length) { cursor.value = null; return; }
    const index = choices.findIndex(option => option.value === activeValue.value);
    const destination = direction === "first" ? 0 : direction === "last" ? choices.length - 1 : (index + direction + choices.length) % choices.length;
    setActiveValue(choices[destination]!.value);
  }
  function remove(key: string) {
    if (!disabled.value) value.value = ((value.value ?? []) as string[]).filter(selected => selected !== key);
  }
  function select(key: string) {
    if (disabled.value || items.value.get(key)?.disabled) return;
    if (!multiple) {
      value.value = key;
      setOpen(false, true);
      return;
    }
    const selected = (value.value ?? []) as string[];
    value.value = selected.includes(key) ? selected.filter(entry => entry !== key) : [...selected, key];
    query.value = "";
    focusInput();
  }
  function keydown(event: KeyboardEvent) {
    if (event.defaultPrevented || disabled.value) return;
    if (event.key === "Escape") {
      if (layer.claimEscape(event)) setOpen(false, true);
      return;
    }
    switch (event.key) {
      case "ArrowUp": case "ArrowDown":
        event.preventDefault();
        if (open.value) moveActive(event.key === "ArrowDown" ? 1 : -1);
        else setOpen(true);
        break;
      case "Home": case "End":
        if (!open.value) break;
        event.preventDefault();
        moveActive(event.key === "Home" ? "first" : "last");
        break;
      case "Enter":
        event.preventDefault();
        if (!open.value) setOpen(true);
        else if (activeValue.value !== null) select(activeValue.value);
        break;
      case "Backspace": {
        const selected = value.value as string[] | undefined;
        if (multiple && !query.value && selected?.length) {
          event.preventDefault();
          remove(selected[selected.length - 1]!);
        }
        break;
      }
    }
  }
  function outside(event: Event) {
    if (!open.value || layer.containsHigher(event.target)) return;
    const target = event.target as Node | null;
    if (target && !triggerRef.value?.contains(target) && !contentRef.value?.contains(target)) setOpen(false);
  }
  function escape(event: KeyboardEvent) {
    if (layer.claimEscape(event)) setOpen(false, true);
  }
  function setQuery(requested: string) {
    query.value = requested;
    void nextTick(() => {
      if (disposed || !inputRef.value) return;
      const key = value.value as string | undefined;
      inputRef.value.value = multiple || open.value ? query.value : key === undefined ? "" : (items.value.get(key)?.label ?? key);
    });
  }
  watch([visibleQuery, available], () => {
    if (cursor.value && (cursor.value.query !== visibleQuery.value || !available.value.some(option => option.value === cursor.value!.key))) cursor.value = null;
  }, { flush: "sync" });
  watch(open, opened => {
    if (opened) { visited.value = true; focusInput(); }
    else { exitQuery.value = query.value; query.value = ""; }
  }, { flush: "sync" });
  watch(query, search => { if (open.value) exitQuery.value = search; }, { flush: "sync" });
  watch(activeItemId, () => void nextTick(() => {
    if (disposed || !open.value || activeValue.value === null) return;
    const row = items.value.get(activeValue.value)?.element;
    const viewport = contentRef.value?.querySelector<HTMLElement>("[role=listbox]");
    if (!row || !viewport) return;
    const itemBounds = row.getBoundingClientRect(), viewBounds = viewport.getBoundingClientRect();
    const adjustment = itemBounds.top < viewBounds.top ? itemBounds.top - viewBounds.top : itemBounds.bottom > viewBounds.bottom ? itemBounds.bottom - viewBounds.bottom : 0;
    viewport.scrollTop += adjustment;
  }), { flush: "post" });
  onMounted(() => {
    document.addEventListener("pointerdown", outside);
    document.addEventListener("focusin", outside);
    document.addEventListener("keydown", escape);
  });
  onBeforeUnmount(() => {
    disposed = true;
    document.removeEventListener("pointerdown", outside);
    document.removeEventListener("focusin", outside);
    document.removeEventListener("keydown", escape);
  });
  return {
    value, values: computed(() => (value.value ?? []) as string[]), open, query,
    disabled, reduce, triggerId, inputId, listId, activeLayoutId, inputRef, triggerRef,
    contentRef, items, activeValue, activeItemId, visibleCount: computed(() => visible.value.length),
    isVisible, hasVisibleItems: (groupId: string) => visible.value.some(option => option.groupId === groupId),
    labelFor: (key?: string) => key === undefined ? undefined : (items.value.get(key)?.label ?? key),
    registerItem, unregisterItem, setOpen, setQuery, setActiveValue, moveActive, select, remove, focusInput, keydown,
  };
}

